package gn

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/bitsinfra/gnomon/cli/internal/testdb"
)

// An export restores and dumps again cleanly; no original value of a masked column appears in
// it; its row counts equal the branch's views; a subset keeps the parents of its rows.
func TestExport(t *testing.T) {
	dsn := testdb.New(t, t.Name())
	testdb.Exec(t, dsn,
		"create table cust (id int generated by default as identity primary key, email text not null, region text not null)",
		"create table ord (id bigserial primary key, cust int not null references cust(id), total int not null)",
		"create index on ord (cust)",
		"insert into cust (email, region) select 'person' || g || '@real.example', case when g % 2 = 0 then 'eu' else 'us' end from generate_series(1, 20) g",
		"insert into ord (cust, total) select 1 + g % 20, g from generate_series(1, 60) g",
		"select gnomon.track('cust')", "select gnomon.track('ord')",
		"select gnomon.create_mask_profile('dev')",
		"select gnomon.add_mask_rule('dev', 'cust', 'email', 'md5(email) || ''@masked.example''')",
		"select gnomon.build_mask_profile('dev')",
		"select gnomon.create_branch('feat')",
		"select gnomon.use('feat'); insert into cust (email, region) values ('new@real.example', 'eu'); update ord set total = 0 where id = 1")
	ctx := context.Background()
	c, err := Connect(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer c.Close(ctx)
	dir := filepath.Join(t.TempDir(), "out")
	if err := Export(ctx, c, ExportOptions{Branch: "feat", Mask: "dev", To: dir}); err != nil {
		t.Fatal(err)
	}
	data, _ := os.ReadFile(filepath.Join(dir, "data.sql"))
	if strings.Contains(string(data), "@real.example") {
		t.Fatal("a masked value leaked into the export")
	}
	post, _ := os.ReadFile(filepath.Join(dir, "post.sql"))
	if strings.Contains(string(post), "gnomon_") || strings.Contains(string(post), "_gnomon") {
		t.Fatalf("gnomon objects in post-data:\n%s", post)
	}
	target := testdb.New(t, t.Name()+"_target")
	testdb.Exec(t, target, "drop extension gnomon cascade")
	for _, f := range []string{"pre.sql", "data.sql", "post.sql"} {
		if out, err := exec.Command("psql", "-X", "-q", "-v", "ON_ERROR_STOP=1", "-d", target, "-f", filepath.Join(dir, f)).CombinedOutput(); err != nil {
			t.Fatalf("restore %s: %v\n%s", f, err, out)
		}
	}
	if got := testdb.Scalar(t, target, "select count(*) from cust"); got != "21" {
		t.Fatalf("cust rows: %s (the branch has 21)", got)
	}
	if got := testdb.Scalar(t, target, "select total from ord where id = 1"); got != "0" {
		t.Fatalf("the branch's change: %s", got)
	}
	testdb.Exec(t, target, "insert into cust (email, region) values ('x', 'eu')") // the sequence moved past the rows
	if out, err := exec.Command("pg_dump", "-d", target, "-f", filepath.Join(t.TempDir(), "again.sql")).CombinedOutput(); err != nil {
		t.Fatalf("dump again: %v %s", err, out)
	}
	// a subset: EU customers' orders, with their customers (and no others)
	dir2 := filepath.Join(t.TempDir(), "subset")
	if err := Export(ctx, c, ExportOptions{Branch: "main", Where: []string{"ord: total > 50"}, Tables: []string{"cust", "ord"}, To: dir2}); err != nil {
		t.Fatal(err)
	}
	target2 := testdb.New(t, t.Name()+"_subset")
	testdb.Exec(t, target2, "drop extension gnomon cascade")
	for _, f := range []string{"pre.sql", "data.sql", "post.sql"} {
		if out, err := exec.Command("psql", "-X", "-q", "-v", "ON_ERROR_STOP=1", "-d", target2, "-f", filepath.Join(dir2, f)).CombinedOutput(); err != nil {
			t.Fatalf("restore subset %s: %v\n%s", f, err, out)
		}
	}
	if got := testdb.Scalar(t, target2, "select count(*) from ord"); got != "10" {
		t.Fatalf("subset orders: %s", got)
	}
	if got := testdb.Scalar(t, target2, "select count(*) from ord o where not exists (select 1 from cust c where c.id = o.cust)"); got != "0" {
		t.Fatal("orphans in the subset")
	}
}
